import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { AppError } from '../utils/appError';
import { catchAsync } from '../utils/catchAsync';

export interface AuthRequest extends Request {
  user?: {
    userId: string;
    userType: string;
  };
}

export const auth = (roles: string[]) => {
  return catchAsync(async (req: AuthRequest, res: Response, next: NextFunction) => {
    // Get token from header
    const token = req.header('Authorization')?.replace('Bearer ', '');

    if (!token) {
      throw new AppError('No authentication token, access denied', 401);
    }

    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key') as { id: string; userType: string };
      
      if (!roles.includes(decoded.userType)) {
        throw new AppError('Not authorized to access this route', 403);
      }

      req.user = {
        userId: decoded.id,
        userType: decoded.userType
      };
      
      next();
    } catch (error) {
      throw new AppError('Token is not valid', 401);
    }
  });
};

export const checkRole = (roles: string[]) => {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user || !roles.includes(req.user.userType)) {
      throw new AppError('Not authorized to access this route', 403);
    }
    next();
  };
}; 